bool BufferedFile::ensure( std::streamoff pos )
{
    if( pos < 0 || pos >= m_size ) {
        return false;
    }

    if( pos >= m_buf_start && pos < m_buf_start + (std::streamoff)m_buf_len ) {
        return true;
    }

    const std::streamoff start = (pos / (std::streamoff)m_block_size) * (std::streamoff)m_block_size;

    m_in.clear();
    m_in.seekg( start, std::ios_base::beg );
    m_in.read( m_buf.data(), (std::streamsize)m_buf.size() );
    m_buf_len   = (std::size_t)m_in.gcount();
    m_buf_start = start;

    return pos < m_buf_start + (std::streamoff)m_buf_len;
}
